  sealed class RomanPaintMesh {public readonly List<Vector3> vertices=new List<Vector3>();public readonly List<Vector3> normals=new List<Vector3>();public readonly List<int> triangles=new List<int>();}
  // Bake geometry while its authoring transforms still exist. Sculptures retain editable parts.
  static GameObject RomanQualityModel(string name,Action<Transform> build,bool sculpture=false){
   modelName=name;meshNumber=0;var root=new GameObject(name);build(root.transform);AuditEgyptModel(root);
   if(!sculpture){var batches=new Dictionary<Material,RomanPaintMesh>();
    foreach(var filter in root.GetComponentsInChildren<MeshFilter>()){var renderer=filter.GetComponent<Renderer>();var mesh=filter.sharedMesh;if(!mesh||!renderer)continue;var vertices=mesh.vertices;var normals=mesh.normals;var matrix=root.transform.worldToLocalMatrix*filter.transform.localToWorldMatrix;var normalMatrix=matrix.inverse.transpose;
     for(int sub=0;sub<mesh.subMeshCount;sub++){var material=renderer.sharedMaterials[Mathf.Min(sub,renderer.sharedMaterials.Length-1)];if(!batches.ContainsKey(material))batches[material]=new RomanPaintMesh();var batch=batches[material];foreach(var i in mesh.GetTriangles(sub)){batch.triangles.Add(batch.vertices.Count);batch.vertices.Add(matrix.MultiplyPoint3x4(vertices[i]));batch.normals.Add(normalMatrix.MultiplyVector(normals[i]).normalized);}}}
    foreach(Transform child in root.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);
    int part=0;foreach(var pair in batches){string path=themeFolder+"/Meshes/"+name+"_QualityBatch_"+(part++)+".asset";var mesh=new Mesh{name=System.IO.Path.GetFileNameWithoutExtension(path),indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(pair.Value.vertices);mesh.SetNormals(pair.Value.normals);mesh.SetTriangles(pair.Value.triangles,0);mesh.RecalculateBounds();var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){RefreshGeneratedMesh(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);}else{AssetDatabase.CreateAsset(mesh,path);saved=mesh;}var go=new GameObject(pair.Key.name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=saved;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=pair.Key;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;}
   }
   Folder(themeFolder+"/Models");var prefab=PrefabUtility.SaveAsPrefabAsset(root,themeFolder+"/Models/"+name+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;
  }
