  static void ApplyRomanPixelPaint(){var shader=Shader.Find("Speed Stars/Desert Pixel Paint");foreach(var guid in AssetDatabase.FindAssets("t:Material",new[]{themeFolder+"/Materials"})){var mat=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));if(mat.shader.name!="Speed Stars/Pastel Street Prop"&&mat.shader!=shader)continue;mat.shader=shader;mat.SetFloat("_PixelSize",.12f);mat.SetFloat("_Grain",mat.name.Contains("Horizon")||mat.name.Contains("Mountain")||mat.name.Contains("Ground")||mat.name.Contains("Paving")?.01f:.025f);EditorUtility.SetDirty(mat);}}
